"""Record layouts for accounts. Generated by Séance from the COBOL record descriptions. Do not edit."""

from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal

from seance.cobol_num import deedit, format_alpha, format_edited, format_numeric, parse_numeric

IN_WIDTH = 38
OUT_WIDTH = 53


@dataclass
class InRecord:
    no: str
    balance: Decimal
    limit: Decimal
    rate: Decimal
    type: str
    months: Decimal
    filler: str

    @classmethod
    def parse(cls, line: str) -> "InRecord":
        line = line.ljust(38)
        return cls(
            no=line[0:8].rstrip(),
            balance=parse_numeric(line[8:17], 9, 2, True, 'trailing_over'),
            limit=parse_numeric(line[17:26], 9, 2, False, 'none'),
            rate=parse_numeric(line[26:30], 4, 4, False, 'none'),
            type=line[30:31].rstrip(),
            months=parse_numeric(line[31:33], 2, 0, False, 'none'),
            filler=line[33:38].rstrip(),
        )

    def format(self) -> str:
        return (
            format_alpha(self.no, 8)
            + format_numeric(self.balance, 9, 2, True, 'trailing_over')
            + format_numeric(self.limit, 9, 2, False, 'none')
            + format_numeric(self.rate, 4, 4, False, 'none')
            + format_alpha(self.type, 1)
            + format_numeric(self.months, 2, 0, False, 'none')
            + format_alpha(self.filler, 5)
        ).rstrip()


@dataclass
class OutRecord:
    acct_no: str
    new_bal: Decimal
    fee: Decimal
    interest: Decimal
    status: str
    shown: Decimal

    @classmethod
    def parse(cls, line: str) -> "OutRecord":
        line = line.ljust(53)
        return cls(
            acct_no=line[0:8].rstrip(),
            new_bal=parse_numeric(line[8:17], 9, 2, True, 'trailing_over'),
            fee=parse_numeric(line[17:22], 5, 2, False, 'none'),
            interest=parse_numeric(line[22:29], 7, 2, False, 'none'),
            status=line[29:39].rstrip(),
            shown=deedit(line[39:53]),
        )

    def format(self) -> str:
        return (
            format_alpha(self.acct_no, 8)
            + format_numeric(self.new_bal, 9, 2, True, 'trailing_over')
            + format_numeric(self.fee, 5, 2, False, 'none')
            + format_numeric(self.interest, 7, 2, False, 'none')
            + format_alpha(self.status, 10)
            + format_edited(self.shown, '$$,$$$,$$9.99-').ljust(14)[:14]
        ).rstrip()

